from orders.domain.catalog import Product


def order(api, customer_id="c1", *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_lists_lines_in_item_order_with_catalogue_names(shop):
    oid = order(shop, "c2", ("PEN", 4), ("BOOK", 1), ("LAMP", 2)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 200
    assert response.body == {
        "order_id": oid,
        "customer_name": "Grace",
        "lines": [
            {"sku": "PEN", "name": "Pen", "quantity": 4},
            {"sku": "BOOK", "name": "Book", "quantity": 1},
            {"sku": "LAMP", "name": "Lamp", "quantity": 2},
        ],
    }


def test_packing_slip_has_no_prices(shop):
    oid = order(shop, "c1", ("BOOK", 2)).body["order_id"]
    line = shop.fulfilment.handle_packing_slip(oid).body["lines"][0]
    assert set(line) == {"sku", "name", "quantity"}


def test_packing_slip_unknown_order_is_404(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_for_cancelled_order_is_409(shop):
    oid = order(shop, "c1", ("LAMP", 2)).body["order_id"]
    assert shop.orders.handle_cancel(oid).status == 200
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 409
    assert "error" in response.body


def test_fulfilment_is_exposed_on_api(api):
    assert api.fulfilment is not None


def test_low_stock_is_strictly_below_threshold_sorted_by_on_hand_then_sku(shop):
    # shop: BOOK=50, LAMP=5, PEN=100. Add more to exercise ties and ordering.
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "APP", "name": "Apple", "unit_price_cents": 50, "on_hand": 2})
    response = shop.fulfilment.handle_low_stock(10)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "APP", "name": "Apple", "on_hand": 2},
        {"sku": "CUP", "name": "Cup", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]}


def test_low_stock_excludes_products_at_threshold(shop):
    body = shop.fulfilment.handle_low_stock(5).body
    assert body == {"products": []}
    assert [p["sku"] for p in shop.fulfilment.handle_low_stock(6).body["products"]] == ["LAMP"]


def test_low_stock_excludes_inactive_products(shop):
    # No controller can deactivate a product yet, so seed one directly.
    shop.fulfilment._service._catalog.add(Product("OLD", "Old", 100, active=False))
    shop.fulfilment._service._stock.set("OLD", 0)
    skus = [p["sku"] for p in shop.fulfilment.handle_low_stock(1).body["products"]]
    assert "OLD" not in skus


def test_low_stock_rejects_invalid_threshold(shop):
    for bad in (-1, "5", 2.5, None, True, False):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400
        assert "threshold" in response.body["error"]


